//event back from road detailgit  to main map
function duankhac(e) {
    let roadId = e.data.regionId;
    $("#" + roadId).css("fill", "", "important");

    //remove road detail from HTML
    $("." + roadId).remove();
    $(".footer").hide();
    $("#mapsvg").show();
    // $(".main-footer").show();
}

//get road detail html
function getDoanDuongContent(road) {
    ROAD_DETAIL_CONTENT[road].html = dataDuan[road];
    return 0;
    var doanduongId = ROAD_DETAIL_CONTENT[road].id;
    var filePath = "./doanduong-content/" + doanduongId + ".html";
    var rawFile = new XMLHttpRequest();
    rawFile.open("GET", filePath, false);
    rawFile.onreadystatechange = function () {
        if (rawFile.readyState === 4) {
            if (rawFile.status === 200 || rawFile.status == 0) {
                var allText = rawFile.responseText;
                ROAD_DETAIL_CONTENT[road].html = allText;
            } else {
                console.log(
                    "Not Found Road Detail - ",
                    ROAD_DETAIL_CONTENT[road].id
                );
            }
        }
    };
    rawFile.send(null);
}

//get all road detail html to ROAD_DETAIL_CONTENT as string HTML
for (let road in ROAD_DETAIL_CONTENT) {
    getDoanDuongContent(road);
}

function hideMainMapContent() {
    $("#mapsvg").hide();
    // $(".main-footer").hide();
    $(".footer").show();
}
