function artChart(id, data, dv){
    new Chart(id, {
        type: 'bar',
        data: data,
        options: {
            indexAxis: 'y',
            scales: {
                
                x: {
                    grid: {
                        display: false
                    },
                    ticks: {
                        callback: function(value, index, ticks) {
                            return value.toLocaleString("es-CO")
                            let max =  ticks[ticks.length-1].value 
                            if (value === max) {
                                return dv == "km" ? value + '     km' : value + '     tỷ đồng';
                              } else {
                                return value;
                              }
                        }
                    }
                },
                y: {
                    grid: {
                        display: false
                    },
                    ticks:{
                        callback: function(value, index, ticks){
                            return '';
                        }
                    }
                }
            },
            plugins: {
                subtitle: {
                    display: true,
                    text: '(đơn vị: '+ (dv == "km" ? 'km)' : 'tỷ đồng)'),
                    position: 'bottom',
                    padding:{
                        top: 10
                    },
                    font:{
                        style: 'italic'
                    }
                },
                legend:{
                    display: false,
                    labels: {
                        font:{
                            style: 'bold',
                            weight: '500'
                        }
                    }
                },
                datalabels: {
                    formatter: function(value, context) {
                        if(context.active === true){
                            return "";
                        }else{
                            return value.toLocaleString("es-CO")
                        }
                    }
                },
                tooltip: {
                    callbacks: {
                        label: function (context) {
                            let label = '';
                            if (context.parsed.x !== null) {
                                label += context.parsed.x.toLocaleString("es-CO")
                            }
                            return label;
                        }
                    }
                }
            }
        },
        plugins:[ChartDataLabels],
    });
}
